const users = [{ id: 1, name: "Ada" }, { id: 2, name: "Alan" }, { id: 3, name: "Grace" }];
const tasks = [
  { userId: 1, title: "Buy milk" },
  { userId: 2, title: "Fix bike" },
  { userId: 1, title: "Write report" },
];

function leftJoin(users, tasks) {
  return users.flatMap((u) => {
    const mine = tasks.filter((t) => t.userId === u.id);
    if (mine.length === 0) return [{ name: u.name, title: null }];
    return mine.map((t) => ({ name: u.name, title: t.title }));
  });
}

console.log(leftJoin(users, tasks));

