const tasks = [
  { owner: "Ada", done: false, estimate: 120 },
  { owner: "Alan", done: false, estimate: 60 },
  { owner: "Ada", done: true, estimate: 30 },
  { owner: "Alan", done: true, estimate: 90 },
  { owner: "Grace", done: false, estimate: 75 },
];

function busyOwners(tasks, limit) {
  const totals = new Map();
  for (const t of tasks) {
    if (t.done) continue;
    totals.set(t.owner, (totals.get(t.owner) ?? 0) + t.estimate);
  }
  return [...totals].filter(([, total]) => total > limit).map(([owner]) => owner);
}

console.log(busyOwners(tasks, 60));

