const log = [];
const pool = {
  async connect() {
    log.push("connect");
    return {
      async query(sql) { log.push(sql); },
      release() { log.push("release"); },
    };
  },
};

async function withTransaction(pool, work) {
  const client = await pool.connect();
  try {
    await client.query("begin");
    const result = await work(client);
    await client.query("commit");
    return result;
  } catch (error) {
    await client.query("rollback");
    throw error;
  } finally {
    client.release();
  }
}

await withTransaction(pool, async (client) => client.query("update tasks set done = true"));
console.log(log.join(", "));
log.length = 0;
try {
  await withTransaction(pool, async () => { throw new Error("check failed"); });
} catch (error) {
  log.push(`error: ${error.message}`);
}
console.log(log.join(", "));

