  const url = env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");
  return url;
}

for (const env of [{}, { DATABASE_URL: "" }, { DATABASE_URL: "postgres://app@db:5432/tasks" }]) {
